SELECT * FROM (
WITH session_data AS (SELECT fb.symbol, MIN(fb.open) OVER (PARTITION BY fb.symbol) AS first_open, MAX(fb.close) OVER (PARTITION BY fb.symbol) AS last_close FROM MARKET_AGENT.GOLD.FCT_BARS AS fb WHERE fb.date_key = (SELECT MAX(date_key) FROM MARKET_AGENT.GOLD.FCT_BARS)) SELECT sd.symbol, (sd.last_close - sd.first_open) / sd.first_open AS session_return FROM session_data AS sd ORDER BY session_return DESC LIMIT 1
) LIMIT 1000

SELECT * FROM (
WITH session_data AS (SELECT fb.symbol, MIN(fb.open) OVER (PARTITION BY fb.symbol) AS first_open, MAX(fb.close) OVER (PARTITION BY fb.symbol) AS last_close FROM MARKET_AGENT.GOLD.FCT_BARS AS fb WHERE fb.date_key = (SELECT MAX(date_key) FROM MARKET_AGENT.GOLD.FCT_BARS)) SELECT sd.symbol, (sd.last_close - sd.first_open) / sd.first_open AS session_return FROM session_data AS sd ORDER BY session_return ASC LIMIT 1
) LIMIT 1000

SELECT * FROM (
SELECT SUM(volume) AS total_volume FROM MARKET_AGENT.GOLD.FCT_BARS WHERE symbol = 'TSLA'
) LIMIT 1000

SELECT * FROM (
SELECT AVG(close) AS avg_closing_price FROM MARKET_AGENT.GOLD.FCT_BARS WHERE symbol = 'AAPL'
) LIMIT 1000

SELECT * FROM (
SELECT COUNT(*) AS trade_count FROM MARKET_AGENT.GOLD.FCT_TRADES WHERE symbol = 'GOOGL'
) LIMIT 1000

SELECT * FROM (
SELECT MAX(high) AS highest_price FROM MARKET_AGENT.GOLD.FCT_BARS WHERE symbol = 'AMZN' AND date_key = (SELECT MAX(date_key) FROM MARKET_AGENT.GOLD.FCT_BARS)
) LIMIT 1000

SELECT * FROM (
SELECT s.sector, SUM(b.volume) AS total_volume FROM MARKET_AGENT.GOLD.FCT_BARS AS b JOIN MARKET_AGENT.GOLD.DIM_SYMBOLS AS s ON b.symbol = s.symbol GROUP BY s.sector ORDER BY total_volume DESC LIMIT 1
) LIMIT 1000

SELECT * FROM (
SELECT COUNT(*) AS suspect_bars_count FROM MARKET_AGENT.GOLD.FCT_BARS WHERE is_suspect = TRUE
) LIMIT 1000

SELECT * FROM (
SELECT close AS closing_price FROM MARKET_AGENT.GOLD.FCT_BARS WHERE symbol = 'MSFT' AND date_key = (SELECT MAX(date_key) FROM MARKET_AGENT.GOLD.FCT_BARS) AND bar_ts = (SELECT MAX(bar_ts) FROM MARKET_AGENT.GOLD.FCT_BARS WHERE symbol = 'MSFT')
) LIMIT 1000

SELECT * FROM (
WITH intraday_range AS (SELECT symbol, MIN(low) OVER (PARTITION BY symbol) AS min_low, MAX(high) OVER (PARTITION BY symbol) AS max_high FROM MARKET_AGENT.GOLD.FCT_BARS) SELECT symbol, (max_high - min_low) / min_low AS intraday_range_percentage FROM intraday_range ORDER BY intraday_range_percentage DESC LIMIT 1
) LIMIT 1000

SELECT * FROM (
SELECT SUM(notional) AS total_notional_value FROM MARKET_AGENT.GOLD.FCT_TRADES
) LIMIT 1000

SELECT * FROM (
SELECT s.symbol, s.company_name, s.sector, STDDEV(b.bar_return) AS volatility FROM MARKET_AGENT.GOLD.FCT_BARS AS b JOIN MARKET_AGENT.GOLD.DIM_SYMBOLS AS s ON b.symbol = s.symbol GROUP BY s.symbol, s.company_name, s.sector ORDER BY volatility DESC LIMIT 1
) LIMIT 1000

SELECT * FROM (
SELECT COUNT(*) AS bar_count FROM MARKET_AGENT.GOLD.FCT_BARS WHERE symbol = 'AAPL'
) LIMIT 1000

SELECT * FROM (
SELECT AVG(size) AS average_trade_size FROM MARKET_AGENT.GOLD.FCT_TRADES
) LIMIT 1000

SELECT * FROM (
SELECT MIN(price) AS lowest_trade_price FROM MARKET_AGENT.GOLD.FCT_TRADES WHERE symbol = 'GOOGL'
) LIMIT 1000
